select
pci.nose_width, b.MONTH_PLAN_QTY as monthPlan, b.MONTH_REMAIN_QTY as monthPlanOs, fq.CLASS1_FINISH_QTY as class1FinishQty, fq.CLASS2_FINISH_QTY as class2FinishQty, fq.CLASS3_FINISH_QTY as class3FinishQty, fq.CLASS4_FINISH_QTY as class4FinishQty, fq.CLASS5_FINISH_QTY as class5FinishQty, SC.COLOR_TYPE, SC.COLOR_CODE, CS.OVER_TIME_STOCK, MS.OVER_TIME_STOCK AS overTimeMonthStock, pa.PLAN_MODIFY_QTY, NVL(MNF.CLASS1_FINISH_QTY, 0) + NVL(MNF.CLASS1_FINISH_QTY, 0) - NVL(a.CLASS1_PLAN_QTY, 0) - NVL(a.CLASS2_PLAN_QTY, 0) min_night_difference_qty, sr.MONTH_PLAN_APS_VERSION, log.change_cx_machine, log.change_class1_plan, log.change_class2_plan, log.change_class3_plan, log.change_class4_plan, log.change_class5_plan from T_CX_SCHEDULE_RESULT a inner join T_CX_AUTO_SCHEDULE_RECORD sr on a.CX_BATCH_NO= sr.CX_BATCH_NO and sr.DEL_FLAG='0' and sr.STATUS='0' LEFT JOIN T_MID_NIGHT_SHIFT_FINISH MNF ON mnf.FINISH_DATE = a.SCHEDULE_DATE AND mnf.CX_MACHINE_CODE = a.CX_MACHINE_CODE AND mnf.EMBRYO_CODE = a.EMBRYO_CODE AND mnf.BOM_DATA_VERSION = a.BOM_DATA_VERSION AND mnf.DEL_FLAG = '0' LEFT JOIN t_product_construction_info pci on a.EMBRYO_CODE = pci.EMBRYO_CODE and a.BOM_DATA_VERSION = pci.EMBRYO_VERSION and pci.DEL_FLAG = '0' LEFT JOIN ( select sum(PLAN_MODIFY_QTY) as PLAN_MODIFY_QTY,MONTH_PLAN_APS_VERSION,EMBRYO_CODE,BOM_DATA_VERSION from T_CX_MONTH_PLAN_ADJUST where DEL_FLAG='0' GROUP BY MONTH_PLAN_APS_VERSION,EMBRYO_CODE,BOM_DATA_VERSION ) pa on pa.EMBRYO_CODE=a.EMBRYO_CODE and pa.MONTH_PLAN_APS_VERSION=sr.MONTH_PLAN_APS_VERSION and pa.BOM_DATA_VERSION=a.BOM_DATA_VERSION LEFT JOIN (
and re.schedule_date = #{scheduleDate} union select casr.cx_batch_no,psl.MATERIAL_CODE,psl.MONTH_PLAN_QTY,psl.MONTH_REMAIN_QTY,1 order_sort from T_CX_AUTO_SCHEDULE_RECORD casr join T_PROCEDURE_SURPLUS_LOG psl on casr.month_plan_aps_version=psl.month_plan_aps_version and psl.procedure_code='1'
casr.del_flag='0' and psl.del_flag='0'
and casr.cx_batch_no=( select distinct cx_batch_no from t_cx_schedule_result t
t.del_flag= '0' and t.schedule_date= #{scheduleDate}
) and not exists(
and re.schedule_date = #{scheduleDate} and re.cx_batch_no=casr.cx_batch_no )
) b ON a.CX_BATCH_NO=b.CX_BATCH_NO and a.EMBRYO_CODE=b.MATERIAL_CODE LEFT JOIN T_CX_CLASS_SHIFT_FINISH_QTY fq ON fq.ORDER_NO=a.ORDER_NO and fq.del_flag='0' LEFT JOIN T_CX_SPEC_COLOR SC ON SC.SPEC_DESC=a.spec_desc AND SC.del_Flag = '0' AND SC.STATUS='0' LEFT JOIN T_CX_STOCK CS ON CS.STOCK_DATE=a.schedule_date and CS.BOM_DATA_VERSION=a.BOM_DATA_VERSION and CS.EMBRYO_CODE=a.embryo_code and CS.DEL_FLAG='0' LEFT JOIN T_CX_MONTH_STOCK MS ON TO_CHAR(MS.STOCK_MONTH, 'yyyy-MM')=TO_CHAR(ADD_MONTHS(a.schedule_date,-1), 'yyyy-MM') and MS.BOM_DATA_VERSION=a.BOM_DATA_VERSION AND MS.EMBRYO_CODE=a.embryo_code AND MS.DEL_FLAG='0' LEFT JOIN (/*调度员操作日志，判断调度员是否有做“转机台”或“调量”操作*/ SELECT schedule_id, max(decode(BEFORE_CX_MACHINE_CODE, AFTER_CX_MACHINE_CODE,0,1)) change_cx_machine, max(decode(BEFORE_CLASS1_PLAN, AFTER_CLASS1_PLAN,0,1)) change_class1_plan, max(decode(BEFORE_CLASS2_PLAN, AFTER_CLASS2_PLAN,0,1)) change_class2_plan, max(decode(BEFORE_CLASS3_PLAN, AFTER_CLASS3_PLAN,0,1)) change_class3_plan, max(decode(BEFORE_CLASS4_PLAN, AFTER_CLASS4_PLAN,0,1)) change_class4_plan, max(decode(BEFORE_CLASS5_PLAN, AFTER_CLASS5_PLAN,0,1)) change_class5_plan FROM T_CX_DISPATCHER_LOG where schedule_date = #{scheduleDate} group by schedule_id ) log ON a.id = log.schedule_id where a.del_flag='0' and a.to_product = #{toProduct} and a.task_type = #{taskType} and a.schedule_date = #{scheduleDate} AND instr(a.embryo_code,#{embryoCode}) > 0 AND instr(a.SAP_CODE,#{sapCode}) > 0 and a.production_status = #{productionStatus}
and a.schedule_date >= to_date(#{startTime},'yyyy-MM-dd')
and a.schedule_date <= to_date(#{endTime},'yyyy-MM-dd')
and a.cx_machine_code = #{cxMachineCode} and instr(','||a.lh_machine_code||',', ','||#{lhMachineCode}||',')>0
and a.is_release = #{isRelease} and a.bom_Data_Version = #{bomDataVersion} and a.cx_machine_type = #{cxMachineType} and a.bom_Data_Version is null and a.bom_Data_Version is not null and a.id in #{scheduleId} order by a.spec_dimension asc

