update T_GSQ_SCHEDULE_RESULT
IS_RELEASE=case when ( ( (mid_plan_qty is not null and mid_plan_qty !=#{gsqMidPlanQty,jdbcType=DECIMAL}) or (mid_plan_qty is null and #{gsqMidPlanQty,jdbcType=DECIMAL}!=0) )or ( (night_plan_qty is not null and night_plan_qty != #{gsqNightPlanQty,jdbcType=DECIMAL}) or (night_plan_qty is null and #{gsqNightPlanQty,jdbcType=DECIMAL}!=0) )or ( (day_plan_qty is not null and day_plan_qty !=#{gsqDayPlanQty,jdbcType=DECIMAL}) or (day_plan_qty is null and #{gsqDayPlanQty,jdbcType=DECIMAL}!=0) ) ) then '0' else IS_RELEASE end, mid_plan_qty = #{gsqMidPlanQty,jdbcType=DECIMAL}, night_plan_qty = #{gsqNightPlanQty,jdbcType=DECIMAL}, day_plan_qty = #{gsqDayPlanQty,jdbcType=DECIMAL}
where id = #{id,jdbcType=DECIMAL}

update T_XWYY_SCHEDULE_RESULT

    IS_RELEASE=case when (
    ( (day_plan_qty is not null and day_plan_qty != #{xwyyDayPlanQty,jdbcType=DECIMAL}) or (day_plan_qty is null
    and #{xwyyDayPlanQty,jdbcType=DECIMAL}!=0) )or
    ( (night_plan_qty is not null and night_plan_qty != #{xwyyNightPlanQty,jdbcType=DECIMAL}) or (night_plan_qty
    is null and #{xwyyNightPlanQty,jdbcType=DECIMAL}!=0) )
    ) then '0'
    else IS_RELEASE end,
    day_plan_qty = #{xwyyDayPlanQty,jdbcType=DECIMAL},
    night_plan_qty = #{xwyyNightPlanQty,jdbcType=DECIMAL}

where id = #{id,jdbcType=DECIMAL}

