IS_RELEASE=case when ( ( (mid_plan_qty is not null and mid_plan_qty !=#{tqMidPlanQty,jdbcType=DECIMAL}) or (mid_plan_qty is null and #{tqMidPlanQty,jdbcType=DECIMAL}!=0) )or ( (night_plan_qty is not null and night_plan_qty != #{tqNightPlanQty,jdbcType=DECIMAL}) or (night_plan_qty is null and #{tqNightPlanQty,jdbcType=DECIMAL}!=0) )or ( (day_plan_qty is not null and day_plan_qty !=#{tqDayPlanQty,jdbcType=DECIMAL}) or (day_plan_qty is null and #{tqDayPlanQty,jdbcType=DECIMAL}!=0) ) or ( (next_mid_plan_qty is not null and next_mid_plan_qty !=#{tqNextMidPlanQty,jdbcType=DECIMAL}) or (next_mid_plan_qty is null and #{tqNextMidPlanQty,jdbcType=DECIMAL}!=0) ) ) then '0' else IS_RELEASE end, mid_plan_qty = #{tqMidPlanQty,jdbcType=DECIMAL}, night_plan_qty = #{tqNightPlanQty,jdbcType=DECIMAL}, day_plan_qty = #{tqDayPlanQty,jdbcType=DECIMAL}, next_mid_plan_qty = #{tqNextMidPlanQty,jdbcType=DECIMAL}
