INSERT INTO MES_CX_SCHEDULE_RESULT( CX_BATCH_NO , ORDER_NO , SCHEDULE_DATE , PRODUCTION_STATUS , IS_RELEASE , CX_MACHINE_CODE , CX_MACHINE_NAME , LH_MACHINE_CODE , LH_MACHINE_NAME , LH_MACHINE_QTY , MINIMUM_LH_MACHINE_REQ_QTY , AVAILABLE_MOLD_QTY , MAXIMUM_CLASS_QTY , WORK_SHIFTS , STORAGE_LOCATION , STORAGE_LOCATION_DESC , SAP_CODE , EMBRYO_SAP_CODE , SPEC_DESC , SPEC_DIMENSION , EMBRYO_CODE , LH_MIDDLE_NIGHT_FINISH_QTY , CX_MONTH_FINISH_QTY , REJECT_QTY , NEWEST_PLAN_QTY , CLASS3_PLANNED_QTY , SINGLE_SHIFT_LH_QTY , TOTAL_STOCK , EXTENDED_STOCK , MONTH_STOCK , ACTUAL_OVER_PRODUCTION , EXPECTED_OVER_PRODUCTION , DIFFERENCE_OVER_PRODUCTION , CLASS1_AVAILABLE_LH_SHIFT , CLASS1_PLAN_QTY , CLASS1_ANALYSIS_INPUT , CLASS1_ANALYSIS , CLASS2_AVAILABLE_LH_SHIFT , CLASS2_PLAN_QTY , CLASS2_ANALYSIS_INPUT , CLASS2_ANALYSIS , CLASS3_AVAILABLE_LH_SHIFT , CLASS3_PLAN_QTY , CLASS3_ANALYSIS_INPUT , CLASS3_ANALYSIS , CLASS4_AVAILABLE_LH_SHIFT , CLASS4_PLAN_QTY , CLASS4_ANALYSIS_INPUT , CLASS4_ANALYSIS , CLASS5_AVAILABLE_LH_SHIFT , CLASS5_PLAN_QTY , CLASS5_ANALYSIS_INPUT , CLASS5_ANALYSIS , MARK_CLOSE_OUT_TIP , REMARK , DATA_VERSION , CREATE_DATE , UPDATE_DATE , IS_DELETE , FACTORY_CODE , COMPANY_CODE , BOM_DATA_VERSION ) SELECT R.CX_BATCH_NO , R.ORDER_NO , R.SCHEDULE_DATE , R.PRODUCTION_STATUS , '1' , R.CX_MACHINE_CODE , R.CX_MACHINE_NAME , R.LH_MACHINE_CODE , R.LH_MACHINE_NAME , R.LH_MACHINE_QTY , R.MINIMUM_LH_MACHINE_REQ_QTY , R.AVAILABLE_MOLD_QTY , R.MAXIMUM_CLASS_QTY , R.WORK_SHIFTS , R.STORAGE_LOCATION , SL.DICT_LABEL , R.SAP_CODE , C.SAP_CODE , R.SPEC_DESC , R.SPEC_DIMENSION , R.EMBRYO_CODE , R.LH_MIDDLE_NIGHT_FINISH_QTY , R.CX_MONTH_FINISH_QTY , R.REJECT_QTY , R.NEWEST_PLAN_QTY , R.CLASS3_PLANNED_QTY , R.SINGLE_SHIFT_LH_QTY , R.TOTAL_STOCK , R.EXTENDED_STOCK , R.MONTH_STOCK , R.ACTUAL_OVER_PRODUCTION , R.EXPECTED_OVER_PRODUCTION , R.DIFFERENCE_OVER_PRODUCTION , R.CLASS1_AVAILABLE_LH_SHIFT , R.CLASS1_PLAN_QTY , R.CLASS1_ANALYSIS_INPUT , R.CLASS1_ANALYSIS , R.CLASS2_AVAILABLE_LH_SHIFT , R.CLASS2_PLAN_QTY , R.CLASS2_ANALYSIS_INPUT , R.CLASS2_ANALYSIS , R.CLASS3_AVAILABLE_LH_SHIFT , R.CLASS3_PLAN_QTY , R.CLASS3_ANALYSIS_INPUT , R.CLASS3_ANALYSIS , R.CLASS4_AVAILABLE_LH_SHIFT , R.CLASS4_PLAN_QTY , R.CLASS4_ANALYSIS_INPUT , R.CLASS4_ANALYSIS , R.CLASS5_AVAILABLE_LH_SHIFT , R.CLASS5_PLAN_QTY , R.CLASS5_ANALYSIS_INPUT , R.CLASS5_ANALYSIS , R.MARK_CLOSE_OUT_TIP , R.REMARK , #{dataVersion} DATA_VERSION , sysdate CREATE_DATE , R.UPDATE_TIME UPDATE_DATE , R.DEL_FLAG IS_DELETE, #{factoryCode}, #{companyCode}, R.BOM_DATA_VERSION FROM T_CX_SCHEDULE_RESULT R left JOIN T_PRODUCT_CONSTRUCTION_INFO C ON R.embryo_code = C.embryo_code AND R.BOM_DATA_VERSION=C.EMBRYO_VERSION AND C.del_flag = '0' inner JOIN sys_dict_data sl ON sl.dict_value = r.STORAGE_LOCATION AND sl.dict_type = 'STORAGE_LOCATION' and sl.locale=#{language}
R.del_flag='0' and R.TO_PRODUCT='0'
AND R.id in( WITH temp_table AS (
SELECT ${item} result_id FROM dual
) select result_id from temp_table)
and r.bom_data_version is not null

